package com.hbm.client.reactor.pile.core;
import com.hbm.machine.reactor.pile.core.*;import net.minecraft.nbt.CompoundTag;import net.minecraft.network.chat.Component;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.item.ItemStack;import snownee.jade.api.*;import snownee.jade.api.config.IPluginConfig;
/** Read-only server data for the same real source channels and original CP overlay values. */
@WailaPlugin public final class PileJadePlugin implements IWailaPlugin {
 @Override public void register(IWailaCommonRegistration event){event.registerBlockDataProvider(Provider.INSTANCE,PileTickingBlockEntity.class);}
 @Override public void registerClient(IWailaClientRegistration event){event.registerBlockComponent(Provider.INSTANCE,PileBodyBlock.class);event.registerBlockComponent(Provider.INSTANCE,PileDeviceBlock.class);}
 private enum Provider implements IServerDataProvider<BlockAccessor>,IBlockComponentProvider {INSTANCE;
  @Override public ResourceLocation getUid(){return PileCoreContent.id("pile_state");}
  @Override public void appendServerData(CompoundTag tag,BlockAccessor accessor){if(!(accessor.getBlockEntity() instanceof PileTickingBlockEntity tile))return;var data=new CompoundTag();data.putInt("meta",tile.getBlockMetadata());if(tile instanceof TileEntityPileCore core){data.putString("kind","core");data.putDouble("temp",core.highestHeat);}else if(tile instanceof TileEntityPileLoader loader){data.putString("kind","loader");data.putDouble("temp",loader.channelTemp);data.putDouble("depletion",loader.channelDepletion);if(loader.stack!=null)data.put("loading",loader.stack.save(accessor.getLevel().registryAccess()));if(loader.channelStack!=null)data.put("rod",loader.channelStack.save(accessor.getLevel().registryAccess()));}else if(tile instanceof TileEntityPileControl control){data.putString("kind","control");data.putDouble("extraction",control.level);}else data.putString("kind",tile instanceof TileEntityPileBaseMK2?"body":"vent");tag.put("hbm:pile",data);}
  @Override public void appendTooltip(ITooltip tooltip,BlockAccessor accessor,IPluginConfig config){var root=accessor.getServerData();if(!root.contains("hbm:pile"))return;var data=root.getCompound("hbm:pile");switch(data.getString("kind")){case "core"->tooltip.add(Component.translatable("hud.hbm.pile.max_temp",(int)Math.round(data.getDouble("temp")),800));case "loader"->{tooltip.add(Component.translatable("hud.hbm.pile.temp",(int)Math.round(data.getDouble("temp")),800));if(data.contains("loading")){var stack=ItemStack.parseOptional(accessor.getLevel().registryAccess(),data.getCompound("loading"));if(!stack.isEmpty())tooltip.add(Component.translatable("hud.hbm.pile.loading",stack.getHoverName()));}if(data.contains("rod")){var stack=ItemStack.parseOptional(accessor.getLevel().registryAccess(),data.getCompound("rod"));if(!stack.isEmpty())tooltip.add(Component.translatable("hud.hbm.pile.last_rod",stack.getHoverName()));if(data.getDouble("depletion")>0)tooltip.add(Component.translatable("hud.hbm.pile.depletion",(int)Math.round(data.getDouble("depletion"))));}}case "control"->tooltip.add(Component.translatable("hud.hbm.pile.extraction",(int)(data.getDouble("extraction")*100)));case "body"->{String key=switch(data.getInt("meta")){case 3->"fuel_in";case 4->"fuel_out";case 5->"air_in";case 6->"air_out";case 7->"control_channel";default->null;};if(key!=null)tooltip.add(Component.translatable("hud.hbm.pile."+key));}default->{}}}
 }
}
